using System;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
namespace CalendarWeather;
internal static class ScrollFooterVerification {
 static T? Find<T>(DependencyObject root) where T:DependencyObject {if(root is T target)return target;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var found=Find<T>(VisualTreeHelper.GetChild(root,i));if(found!=null)return found;}return null;}
 internal static async Task<bool> Run(Window window){var panel=Find<SettingsPanel>(window);if(panel?.Content is not DockPanel host||host.Children[0] is not Button button||host.Children[1] is not ScrollViewer scroll)return false;double height=window.Height;try{window.Height=Math.Min(height,400);window.UpdateLayout();scroll.ScrollToTop();await Task.Delay(50);for(int i=0;i<20&&scroll.VerticalOffset<scroll.ScrollableHeight-1;i++){button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(210);}bool bottom=scroll.ScrollableHeight>1&&scroll.VerticalOffset>=scroll.ScrollableHeight-1;button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(220);bool top=scroll.VerticalOffset<1;bool footer=button.Height==20&&Math.Abs(button.TranslatePoint(new Point(0,button.ActualHeight),host).Y-host.ActualHeight)<1;return bottom&&top&&footer&&scroll.VerticalScrollBarVisibility==ScrollBarVisibility.Hidden;}finally{window.Height=height;window.UpdateLayout();}}
}
